fun findUser(id: Long): Map<String, Any>? {
    if (id <= 0) return null
    return mapOf("id" to id, "name" to "user-$id")
}

class Stack<T> {
    private val items = mutableListOf<T>()
    fun push(value: T) = items.add(value)
    fun pop(): T? = items.removeLastOrNull()
}

fun <T, K> List<T>.groupByKey(keyFn: (T) -> K): Map<K, List<T>> {
    val grouped = linkedMapOf<K, MutableList<T>>()
    for (item in this) {
        grouped.getOrPut(keyFn(item)) { mutableListOf() }.add(item)
    }
    return grouped
}

sealed interface Result<out T> {
    data class Ok<T>(val value: T) : Result<T>
    data class Err(val message: String) : Result<Nothing>
}

suspend fun fetchJson(url: String): String {
    return httpClient.get(url).bodyAsText()
}

inline fun <T> retry(attempts: Int = 3, block: () -> T): T {
    var last: Throwable? = null
    repeat(attempts) {
        try {
            return block()
        } catch (t: Throwable) {
            last = t
        }
    }
    throw last!!
}
